hi5:[
["बहिष्कृत हितकारिणी सभेची स्थापना केव्हा झाली?",["1920","1924","1927","1936"],1,"आंबेडकरांनी 1924 मध्ये बहिष्कृत हितकारिणी सभा स्थापन केली: 'शिका, संघटित व्हा, संघर्ष करा'.",{"i":"hi5-001"}],
["काळाराम मंदिर सत्याग्रह कोठे झाला?",["महाड","नाशिक","पुणे","पंढरपूर"],1,"काळाराम मंदिर (नाशिक) प्रवेश सत्याग्रह 1930 मध्ये झाला. महाड चवदार तळे सत्याग्रह 1927.",{"i":"hi5-002"}],
["पुणे करार कोणामध्ये झाला?",["आंबेडकर–टिळक","आंबेडकर–गांधी","गांधी–आयर्विन","नेहरू–जिना"],1,"पुणे करार (24 सप्टेंबर 1932) गांधी व आंबेडकर यांच्यात झाला; स्वतंत्र मतदारसंघाऐवजी राखीव जागा मान्य झाल्या.",{"i":"hi5-003"}],
["आंबेडकरांनी 1936 मध्ये कोणता पक्ष स्थापन केला?",["रिपब्लिकन पक्ष","स्वतंत्र मजूर पक्ष","शेड्युल्ड कास्ट्स फेडरेशन","समता पक्ष"],1,"1936 – स्वतंत्र मजूर पक्ष (Independent Labour Party); 1942 – शेड्युल्ड कास्ट्स फेडरेशन; रिपब्लिकन पक्षाची कल्पना 1956, स्थापना 1957.",{"i":"hi5-004"}],
["आंबेडकरांनी धम्मदीक्षा कोठे घेतली?",["मुंबई","नागपूर","महाड","दिल्ली"],1,"आंबेडकरांनी 14 ऑक्टोबर 1956 रोजी नागपूरच्या दीक्षाभूमीवर बौद्ध धम्माची दीक्षा घेतली.",{"i":"hi5-005"}],
["'जनता' वृत्तपत्र कोणी सुरू केले?",["महात्मा फुले","डॉ. आंबेडकर","शाहू महाराज","आगरकर"],1,"आंबेडकरांची वृत्तपत्रे: मूकनायक (1920), बहिष्कृत भारत (1927), समता (1928), जनता (1930), प्रबुद्ध भारत (1956).",{"i":"hi5-006"}],
["आंबेडकरांनी स्थापन केलेली शिक्षणसंस्था कोणती?",["रयत शिक्षण संस्था","पीपल्स एज्युकेशन सोसायटी","डेक्कन एज्युकेशन सोसायटी","शिवाजी शिक्षण संस्था"],1,"आंबेडकरांनी 1945 मध्ये पीपल्स एज्युकेशन सोसायटी स्थापन केली; मुंबईतील सिद्धार्थ महाविद्यालय हिचेच. रयत शिक्षण संस्था – कर्मवीर भाऊराव पाटील.",{"i":"hi5-007"}],
["महाड चवदार तळे सत्याग्रह कोणत्या हक्कासाठी होता?",["मंदिरप्रवेश","सार्वजनिक पाणी","शिक्षण","मतदान"],1,"महाड चवदार तळे सत्याग्रह (20 मार्च 1927) सार्वजनिक पाणवठ्यावर पाणी भरण्याच्या हक्कासाठी होता.",{"i":"hi5-008"}],
["नाशिक येथील काळाराम मंदिर प्रवेश सत्याग्रह डॉ. आंबेडकरांनी कोणत्या वर्षी सुरू केला?",["1930","1927","1932","1935"],0,"2 मार्च 1930 रोजी नाशिकच्या काळाराम मंदिरात अस्पृश्यांच्या प्रवेशासाठी सत्याग्रह सुरू झाला. 1927 मध्ये महाडचा चवदार तळे सत्याग्रह झाला होता.",{"i":"hi5-009"}],
["डॉ. आंबेडकरांची नियतकालिके व त्यांचे प्रारंभ वर्ष यांच्या जोड्यांपैकी चुकीची जोडी ओळखा.",["मूकनायक — 1920","बहिष्कृत भारत — 1927","जनता — 1930","प्रबुद्ध भारत — 1940"],3,"प्रबुद्ध भारत हे 1956 मध्ये (जनता पत्राचे नाव बदलून) सुरू झाले. मूकनायक (1920, शाहू महाराजांच्या मदतीने), बहिष्कृत भारत (1927) व जनता (1930) बरोबर.",{"i":"hi5-010"}],
["डॉ. आंबेडकरांनी स्थापन केलेल्या 'पीपल्स एज्युकेशन सोसायटी'चे पहिले महाविद्यालय कोणते?",["सिद्धार्थ महाविद्यालय, मुंबई","मिलिंद महाविद्यालय, औरंगाबाद","फर्ग्युसन महाविद्यालय, पुणे","राजाराम महाविद्यालय, कोल्हापूर"],0,"पीपल्स एज्युकेशन सोसायटी 1945 मध्ये स्थापन झाली आणि 1946 मध्ये मुंबईत सिद्धार्थ महाविद्यालय सुरू झाले. मिलिंद महाविद्यालय (औरंगाबाद) 1950 मध्ये सुरू झाले.",{"i":"hi5-011"}]
],
