["1918 मध्ये मुंबईत झालेल्या 'अस्पृश्यता निवारक परिषदे'चे अध्यक्ष कोण होते?",["छत्रपती शाहू महाराज","डॉ. आंबेडकर","सयाजीराव गायकवाड","नानाभाई हरिदास"],2,"सयाजीराव गायकवाड.",{"i":"hi6-009","y":"2022","n":40,"v":"k"}],
["हिंदू विधवांच्या उन्नतीसाठी आयुष्य वेचणारे व विधवा विवाहोत्तेजक मंडळीचे सचिव झालेले कोण?",["महात्मा फुले","सावित्रीबाई फुले","रमाबाई आंबेडकर","महर्षी धोंडो केशव कर्वे"],3,"महर्षी कर्वे यांनी 1893 मध्ये विधवा विवाहोत्तेजक मंडळीचे काम हाती घेतले, स्वतः विधवेशी पुनर्विवाह केला, 1896 मध्ये अनाथ बालिकाश्रम आणि 1916 मध्ये महिला विद्यापीठ स्थापन केले.",{"i":"hi6-010","y":"2023","n":58,"src":"गट-क मुख्य परीक्षा, सामान्य अध्ययन पेपर-II (17 डिसेंबर 2023)"}],
["1897 च्या प्लेगमध्ये कोणत्या कामगार नेत्याचा मृत्यू झाला?",["नारायण मेघाजी लोखंडे","रामचंद्र शिंदे","ना. म. जोशी","रघु कोरगावकर"],0,"भारतीय कामगार चळवळीचे जनक नारायण मेघाजी लोखंडे (बॉम्बे मिल हॅण्ड्स असोसिएशन, 1884; 'दीनबंधू'चे संपादक) यांचे 1897 मध्ये प्लेगग्रस्तांची सेवा करताना प्लेगने निधन झाले.",{"i":"hi6-011","y":"2023","n":60,"src":"गट-क मुख्य परीक्षा, सामान्य अध्ययन पेपर-II (17 डिसेंबर 2023)"}],
["राजर्षी शाहू महाराजांनी 1902 मध्ये कोल्हापूर संस्थानात मागासवर्गीयांसाठी नोकऱ्यांत किती टक्के आरक्षण दिले?",["50%","25%","33%","60%"],0,"26 जुलै 1902 रोजी शाहू महाराजांनी संस्थानातील नोकऱ्यांत ब्राह्मणेतर मागासवर्गीयांसाठी 50% जागा राखीव ठेवण्याचा आदेश काढला. भारतातील आरक्षणाचा हा महत्त्वाचा प्रारंभ मानला जातो.",{"i":"hi6-012"}],
["'वेदोक्त प्रकरण' कोणाशी संबंधित आहे?",["राजर्षी शाहू महाराज","महात्मा फुले","डॉ. आंबेडकर","महर्षी विठ्ठल रामजी शिंदे"],0,"कोल्हापूरच्या राजघराण्यातील धार्मिक विधी वेदोक्त पद्धतीने करण्यास पुरोहिताने नकार दिल्याने (1899 पासून) हा वाद उभा राहिला. त्यातून शाहू महाराज ब्राह्मणेतर चळवळीकडे वळले.",{"i":"hi6-013"}],
["कर्मवीर भाऊराव पाटील यांनी 'रयत शिक्षण संस्था' कोणत्या वर्षी स्थापन केली?",["1919","1909","1932","1945"],0,"1919 मध्ये काले (जि. सातारा) येथे रयत शिक्षण संस्था स्थापन झाली; नंतर ती साताऱ्याला आली. 'कमवा व शिका' हे त्यांचे तत्त्व. 1932 मध्ये पंजाबराव देशमुखांनी श्री शिवाजी शिक्षण संस्था (अमरावती) स्थापन केली.",{"i":"hi6-014"}],
["'सुधारक' हे वृत्तपत्र कोणी सुरू केले?",["गोपाळ गणेश आगरकर","लोकमान्य टिळक","विष्णुशास्त्री चिपळूणकर","लोकहितवादी"],0,"केसरीतून बाहेर पडल्यावर आगरकरांनी 1888 मध्ये 'सुधारक' सुरू केले. 'आधी सामाजिक सुधारणा' हा त्यांचा आग्रह होता, तर टिळकांचा 'आधी राजकीय स्वातंत्र्य' यावर भर होता.",{"i":"hi6-015"}],
["'डिप्रेस्ड क्लासेस मिशन' (भारतीय निराश्रित साहाय्यकारी मंडळी) 1906 मध्ये कोणी स्थापन केली?",["महर्षी विठ्ठल रामजी शिंदे","डॉ. आंबेडकर","राजर्षी शाहू महाराज","गोपाळ बाबा वलंगकर"],0,"महर्षी वि. रा. शिंदे यांनी 18 ऑक्टोबर 1906 रोजी मुंबईत डिप्रेस्ड क्लासेस मिशन स्थापन केले. अस्पृश्यांसाठी शाळा, वसतिगृहे व रोजगाराचे कार्य त्यातून झाले.",{"i":"hi6-016"}],
["स्वच्छतेचा संदेश देत खेडोपाडी कीर्तन करणारे व 'देवकीनंदन गोपाला' भजन गाणारे संत कोण?",["संत गाडगे बाबा","संत तुकडोजी महाराज","साने गुरुजी","विनोबा भावे"],0,"संत गाडगे बाबा (डेबूजी झिंगराजी जानोरकर) यांनी कीर्तनातून स्वच्छता, शिक्षण व अंधश्रद्धा निर्मूलनाचा संदेश दिला. त्यांच्या नावाने महाराष्ट्रात 'संत गाडगेबाबा ग्राम स्वच्छता अभियान' राबवले जाते.",{"i":"hi6-017"}]
