["जगातील सर्वात मोठे उष्ण वाळवंट कोणते?",["सहारा","थर","गोबी","कालाहारी"],0,"उत्तर आफ्रिकेतील सहारा हे सर्वात मोठे उष्ण वाळवंट. गोबी हे आशियातील शीत वाळवंट, थर भारत-पाकिस्तानमध्ये, तर कालाहारी दक्षिण आफ्रिकेत.",{"i":"ge11-012"}],
["जगातील सर्वात मोठे बेट कोणते?",["ग्रीनलँड","न्यू गिनी","बोर्निओ","मादागास्कर"],0,"ग्रीनलँड (डेन्मार्कचा स्वायत्त प्रदेश) हे सर्वात मोठे बेट. ऑस्ट्रेलियाला बेट न मानता खंड मानले जाते. न्यू गिनी दुसरे मोठे बेट.",{"i":"ge11-013"}],
["जगातील महासागरांतील सर्वात खोल ठिकाण (चॅलेंजर डीप) कोणत्या गर्तेत आहे?",["मरियाना गर्ता, पॅसिफिक महासागर","प्युर्टो रिको गर्ता, अटलांटिक महासागर","जावा गर्ता, हिंदी महासागर","टोंगा गर्ता, अटलांटिक महासागर"],0,"पॅसिफिक महासागरातील मरियाना गर्तेतील चॅलेंजर डीप सुमारे 11 किमी खोल आहे. पृथ्वीवरील सर्वात सखल भूभाग मृत समुद्राचा किनारा आहे.",{"i":"ge11-014"}],
["पनामा कालवा कोणते दोन महासागर जोडतो?",["अटलांटिक व पॅसिफिक","अटलांटिक व हिंदी","पॅसिफिक व हिंदी","आर्क्टिक व अटलांटिक"],0,"मध्य अमेरिकेतील पनामा कालवा अटलांटिक व पॅसिफिक महासागर जोडतो. सुएझ कालवा भूमध्य समुद्र व तांबडा समुद्र जोडतो.",{"i":"ge11-015"}],
["आशिया व उत्तर अमेरिका यांना कोणती सामुद्रधुनी वेगळी करते?",["बेरिंग सामुद्रधुनी","मलाक्का सामुद्रधुनी","जिब्राल्टर सामुद्रधुनी","डोव्हर सामुद्रधुनी"],0,"बेरिंग सामुद्रधुनी रशिया (आशिया) व अलास्का (उत्तर अमेरिका) यांच्या दरम्यान आहे. मलाक्का मलेशिया व सुमात्रा (इंडोनेशिया) यांच्या दरम्यान, तर डोव्हर इंग्लंड व फ्रान्स यांच्या दरम्यान.",{"i":"ge11-016"}],
["पश्चिम आफ्रिकेत उष्ण-आर्द्र हवेपासून दिलासा देणाऱ्या कोणत्या कोरड्या वाऱ्याला 'डॉक्टर' वारा म्हणतात?",["हरमट्टन","सिरोक्को","मिस्ट्रल","फॉन"],0,"सहारातून येणारा कोरडा हरमट्टन वारा पश्चिम आफ्रिकेच्या किनारी भागातील दमट हवेपासून दिलासा देतो, म्हणून त्याला 'डॉक्टर' म्हणतात. फॉन (आल्प्स) व चिनूक (रॉकी) हे उष्ण उताराचे वारे.",{"i":"ge11-017"}],
["जगातील सर्वात मोठी प्रवाळ भित्ती 'ग्रेट बॅरियर रीफ' कोणत्या देशाच्या किनाऱ्यालगत आहे?",["ऑस्ट्रेलिया","इंडोनेशिया","फिलिपिन्स","मालदीव"],0,"ग्रेट बॅरियर रीफ ऑस्ट्रेलियाच्या ईशान्य (क्वीन्सलँड) किनाऱ्यालगत, कोरल समुद्रात आहे. प्रवाळ उष्ण, उथळ व स्वच्छ पाण्यात वाढतात.",{"i":"ge11-018"}],
["विषुववृत्त खालीलपैकी कोणत्या देशातून जात नाही?",["भारत","इक्वेडोर","केनिया","इंडोनेशिया"],0,"विषुववृत्त इक्वेडोर, कोलंबिया, ब्राझील, गॅबॉन, काँगो, युगांडा, केनिया, सोमालिया, मालदीव व इंडोनेशिया इत्यादी देशांतून जाते. भारताचे दक्षिण टोक (इंदिरा पॉइंट) सुमारे 6°45′ उत्तर अक्षांशावर आहे.",{"i":"ge11-019"}],
["कर्कवृत्त भारतातील किती राज्यांतून जाते?",["8","6","7","9"],0,"कर्कवृत्त गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगड, झारखंड, पश्चिम बंगाल, त्रिपुरा व मिझोराम या 8 राज्यांतून जाते. ते महाराष्ट्रातून जात नाही.",{"i":"ge11-020"}],
["क्षेत्रफळाने जगातील सर्वात मोठा देश कोणता?",["रशिया","कॅनडा","चीन","अमेरिका"],0,"रशिया क्षेत्रफळाने सर्वात मोठा; त्यानंतर कॅनडा. भारताचा क्षेत्रफळात सातवा क्रमांक आहे.",{"i":"ge11-021"}]
